#include <list>
#include <iostream>
#include <algorithm>

struct EqualOrClose { bool operator()(int a, int b) const { return std::abs(a - b) <= 1; } };

int main() {
    std::list<int> l = {1, 2, 3, 3, 5, 6, 7, 7, 7, 9};
    // Initial comparison is 2 vs 1 (false). 3 vs 2 (false). 3 vs 3 (true, removed).
    // Next element (5) compared against the last kept element (3).
    l.unique(EqualOrClose());

    // Expected output: 1 2 3 5 6 7 9 
    for (int x : l) { std::cout << x << " "; }
    std::cout << "\n";
}
